INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-shopping-a2-01-01', 'lesson-shopping-a2-01', 1, 'sentence', 'Excuse me, where can I find the rice?', 'Com licença, onde encontro o arroz?', '/ɪkˈskjuːz miː wɛr kæn aɪ faɪnd ðə raɪs/', '"Where can I find" é a pergunta padrão em qualquer loja.', '[]'::jsonb, '[{"surface":"Excuse","pos":"verb","ipa":"/ɪkˈskjuːz/","gloss":"desculpar (excuse me = com licença)"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"find","pos":"verb","ipa":"/faɪnd/","gloss":"encontrar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"rice","pos":"noun","ipa":"/raɪs/","gloss":"arroz"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-01-02', 'lesson-shopping-a2-01', 2, 'sentence', 'It''s in aisle five.', 'Fica no corredor cinco.', '/ɪts ɪn aɪl faɪv/', '"Aisle" = corredor; o "s" é mudo: /aɪl/.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"aisle","pos":"noun","ipa":"/aɪl/","gloss":"corredor"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-01-03', 'lesson-shopping-a2-01', 3, 'sentence', 'I need a pound of ground beef.', 'Preciso de meio quilo de carne moída.', '/aɪ niːd ə paʊnd ʌv ɡraʊnd biːf/', '"Pound" (lb) ≈ 450 g, unidade dos EUA. "Ground beef" = carne moída.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"pound","pos":"noun","ipa":"/paʊnd/","gloss":"libra (peso)"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"ground","pos":"noun","ipa":"/ɡraʊnd/","gloss":"chão, terreno"},{"surface":"beef","pos":"noun","ipa":"/biːf/","gloss":"carne de boi"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-01-04', 'lesson-shopping-a2-01', 4, 'sentence', 'Do you have this in a bigger size?', 'Vocês têm este num tamanho maior?', '/duː juː hæv ðɪs ɪn ə ˈbɪɡər saɪz/', 'Comparativo: "big" → "bigger" (dobra o "g").', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"bigger","pos":"adjective","ipa":"/ˈbɪɡər/","gloss":"maior"},{"surface":"size","pos":"noun","ipa":"/saɪz/","gloss":"tamanho"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-01-05', 'lesson-shopping-a2-01', 5, 'sentence', 'Is this on sale?', 'Isto está em promoção?', '/ɪz ðɪs ɑːn seɪl/', '"On sale" = em promoção; "for sale" = à venda.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"sale","pos":"noun","ipa":"/seɪl/","gloss":"promoção, venda"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-01-06', 'lesson-shopping-a2-01', 6, 'sentence', 'Buy one, get one free.', 'Leve dois, pague um.', '/baɪ wʌn ɡɛt wʌn friː/', 'Promoção comum nos EUA (BOGO). Literal: "compre um, ganhe um grátis".', '[]'::jsonb, '[{"surface":"Buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-01-07', 'lesson-shopping-a2-01', 7, 'sentence', 'Paper or plastic?', 'Sacola de papel ou de plástico?', '/ˈpeɪpər ɔːr ˈplæstɪk/', 'Pergunta do caixa. Muitos lugares cobram pela sacola.', '[]'::jsonb, '[{"surface":"Paper","pos":"noun","ipa":"/ˈpeɪpər/","gloss":"papel"},{"surface":"or","pos":"conjunction","ipa":"/ɔːr/","gloss":"ou"},{"surface":"plastic","pos":"noun","ipa":"/ˈplæstɪk/","gloss":"plástico"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-01-08', 'lesson-shopping-a2-01', 8, 'sentence', 'Do you have a store card?', 'Você tem o cartão da loja?', '/duː juː hæv ə stɔːr kɑːrd/', 'Cartão de fidelidade que dá desconto.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"card","pos":"noun","ipa":"/kɑːrd/","gloss":"cartão"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-01-09', 'lesson-shopping-a2-01', 9, 'sentence', 'Where is the checkout?', 'Onde fica o caixa?', '/wɛr ɪz ðə ˈtʃɛkaʊt/', '"Checkout" = caixa; "self-checkout" = autoatendimento.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"checkout","pos":"noun","ipa":"/ˈtʃɛkaʊt/","gloss":"saída do hotel"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-01-10', 'lesson-shopping-a2-01', 10, 'sentence', 'I forgot my shopping list.', 'Esqueci minha lista de compras.', '/aɪ fərˈɡɑːt maɪ ˈʃɑːpɪŋ lɪst/', '"Shopping list" = lista de compras. Passado irregular: "forgot".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"forgot","pos":"verb","ipa":"/fərˈɡɑːt/","gloss":"esqueceu"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"shopping","pos":"noun","ipa":"/ˈʃɑːpɪŋ/","gloss":"compras"},{"surface":"list","pos":"noun","ipa":"/lɪst/","gloss":"lista"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-shopping-a2-02-01', 'lesson-shopping-a2-02', 1, 'sentence', 'I''m looking for a winter jacket.', 'Estou procurando uma jaqueta de inverno.', '/aɪm ˈlʊkɪŋ fɔːr ə ˈwɪntər ˈdʒækɪt/', '"Look for" = procurar. Presente contínuo para o que você está fazendo.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"looking","pos":"verb","ipa":"/ˈlʊkɪŋ/","gloss":"aguardando (look forward)"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"winter","pos":"noun","ipa":"/ˈwɪntər/","gloss":"inverno"},{"surface":"jacket","pos":"noun","ipa":"/ˈdʒækɪt/","gloss":"jaqueta"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-02-02', 'lesson-shopping-a2-02', 2, 'sentence', 'What size are you?', 'Qual é o seu tamanho?', '/wʌt saɪz ɑːr juː/', 'Pergunta do vendedor. Resposta: "I''m a medium".', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"size","pos":"noun","ipa":"/saɪz/","gloss":"tamanho"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-02-03', 'lesson-shopping-a2-02', 3, 'sentence', 'Does it come in blue?', 'Tem em azul?', '/dʌz ɪt kʌm ɪn bluː/', '"Come in" + cor/tamanho = vir, estar disponível.', '[]'::jsonb, '[{"surface":"Does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"blue","pos":"adjective","ipa":"/bluː/","gloss":"azul"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-02-04', 'lesson-shopping-a2-02', 4, 'sentence', 'Can I try this on?', 'Posso experimentar?', '/kæn aɪ traɪ ðɪs ɑːn/', '"Try on" = experimentar roupa.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-02-05', 'lesson-shopping-a2-02', 5, 'sentence', 'It fits perfectly.', 'Serviu perfeitamente.', '/ɪt fɪts ˈpɜːrfɪktli/', '"Fit" = servir (tamanho). Com he/she/it: "fits".', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"fits","pos":"verb","ipa":"/fɪts/","gloss":"serve"},{"surface":"perfectly","pos":"adverb","ipa":"/ˈpɜːrfɪktli/","gloss":"perfeitamente"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-02-06', 'lesson-shopping-a2-02', 6, 'sentence', 'It''s a little tight.', 'Está um pouco apertado.', '/ɪts ə ˈlɪtəl taɪt/', '"Tight" = apertado; "loose" = folgado.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"},{"surface":"tight","pos":"adjective","ipa":"/taɪt/","gloss":"apertado"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-02-07', 'lesson-shopping-a2-02', 7, 'sentence', 'These shoes are too big.', 'Estes sapatos estão grandes demais.', '/ðiːz ʃuːz ɑːr tuː bɪɡ/', '"Shoes" é plural: "these shoes are".', '[]'::jsonb, '[{"surface":"These","pos":"determiner","ipa":"/ðiːz/","gloss":"estes, estas"},{"surface":"shoes","pos":"noun","ipa":"/ʃuːz/","gloss":"sapatos"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"big","pos":"adjective","ipa":"/bɪɡ/","gloss":"grande"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-02-08', 'lesson-shopping-a2-02', 8, 'sentence', 'It looks good on you.', 'Ficou bem em você.', '/ɪt lʊks ɡʊd ɑːn juː/', '"Look good on" = ficar bem em alguém.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"looks","pos":"verb","ipa":"/lʊks/","gloss":"parece, fica"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-02-09', 'lesson-shopping-a2-02', 9, 'sentence', 'I''ll think about it.', 'Vou pensar.', '/aɪl θɪŋk əˈbaʊt ɪt/', 'Forma educada de não comprar agora.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"think","pos":"verb","ipa":"/θɪŋk/","gloss":"achar, pensar"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-02-10', 'lesson-shopping-a2-02', 10, 'sentence', 'I''ll take the black one.', 'Vou levar a preta.', '/aɪl teɪk ðə blæk wʌn/', '"One" substitui o substantivo: "the black one".', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"black","pos":"adjective","ipa":"/blæk/","gloss":"preto"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-shopping-a2-03-01', 'lesson-shopping-a2-03', 1, 'sentence', 'How would you like to pay?', 'Como você prefere pagar?', '/haʊ wʊd juː laɪk tuː peɪ/', 'Pergunta do caixa. "Would like" = gostaria.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"pay","pos":"verb","ipa":"/peɪ/","gloss":"pagar"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-03-02', 'lesson-shopping-a2-03', 2, 'sentence', 'Can I pay with my phone?', 'Posso pagar com o celular?', '/kæn aɪ peɪ wɪð maɪ foʊn/', '"Pay with" + meio de pagamento; "pay by card", "pay in cash".', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"pay","pos":"verb","ipa":"/peɪ/","gloss":"pagar"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-03-03', 'lesson-shopping-a2-03', 3, 'sentence', 'Insert your card, please.', 'Insira o cartão, por favor.', '/ɪnˈsɜːrt jʊr kɑːrd pliːz/', 'Na maquininha: "insert" (inserir), "tap" (aproximar), "swipe" (passar).', '[]'::jsonb, '[{"surface":"Insert","pos":"verb","ipa":"/ɪnˈsɜːrt/","gloss":"inserir"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"card","pos":"noun","ipa":"/kɑːrd/","gloss":"cartão"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-03-04', 'lesson-shopping-a2-03', 4, 'sentence', 'Tap your card here.', 'Aproxime o cartão aqui.', '/tæp jʊr kɑːrd hɪr/', '"Tap" = encostar, aproximar (pagamento sem contato).', '[]'::jsonb, '[{"surface":"Tap","pos":"noun","ipa":"/tæp/","gloss":"torneira; chope"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"card","pos":"noun","ipa":"/kɑːrd/","gloss":"cartão"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-03-05', 'lesson-shopping-a2-03', 5, 'sentence', 'Enter your PIN.', 'Digite sua senha.', '/ˈɛntər jʊr pɪn/', '"PIN" = senha numérica do cartão. "Enter" = digitar.', '[]'::jsonb, '[{"surface":"Enter","pos":"verb","ipa":"/ˈɛntər/","gloss":"digitar, entrar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"PIN","pos":"noun","ipa":"/pɪn/","gloss":"senha do cartão"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-03-06', 'lesson-shopping-a2-03', 6, 'sentence', 'Your card was declined.', 'Seu cartão foi recusado.', '/jʊr kɑːrd wɑːz dɪˈklaɪnd/', 'Voz passiva: "was declined". Tente outro cartão.', '[]'::jsonb, '[{"surface":"Your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"card","pos":"noun","ipa":"/kɑːrd/","gloss":"cartão"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"declined","pos":"verb","ipa":"/dɪˈklaɪnd/","gloss":"recusado"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-03-07', 'lesson-shopping-a2-03', 7, 'sentence', 'Do you need a receipt?', 'Precisa do recibo?', '/duː juː niːd ə rɪˈsiːt/', '"Receipt" com "p" mudo: /rɪˈsiːt/.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"receipt","pos":"noun","ipa":"/rɪˈsiːt/","gloss":"recibo"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-03-08', 'lesson-shopping-a2-03', 8, 'sentence', 'Can I pay in installments?', 'Posso parcelar?', '/kæn aɪ peɪ ɪn ɪnˈstɔːlmənts/', '"Installments" = parcelas. Pouco comum nos EUA no varejo.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"pay","pos":"verb","ipa":"/peɪ/","gloss":"pagar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"installments","pos":"noun","ipa":"/ɪnˈstɔːlmənts/","gloss":"parcelas"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-03-09', 'lesson-shopping-a2-03', 9, 'sentence', 'Here is your change.', 'Aqui está o seu troco.', '/hɪr ɪz jʊr tʃeɪndʒ/', '"Change" = troco (e também mudança).', '[]'::jsonb, '[{"surface":"Here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-03-10', 'lesson-shopping-a2-03', 10, 'sentence', 'The total is forty-two fifty.', 'O total é quarenta e dois e cinquenta.', '/ðə ˈtoʊtəl ɪz ˌfɔːrtiˈtuː ˈfɪfti/', 'Preços em dólares são lidos em dois blocos: "forty-two fifty" = $42.50.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"total","pos":"noun","ipa":"/ˈtoʊtəl/","gloss":"total"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"forty-two","pos":"numeral","ipa":"/ˌfɔːrtiˈtuː/","gloss":"quarenta e dois"},{"surface":"fifty","pos":"numeral","ipa":"/ˈfɪfti/","gloss":"cinquenta"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-shopping-a2-04-01', 'lesson-shopping-a2-04', 1, 'sentence', 'I''d like to return this.', 'Eu gostaria de devolver isto.', '/aɪd laɪk tuː rɪˈtɜːrn ðɪs/', '"Return" = devolver.', '[]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"return","pos":"adjective","ipa":"/rɪˈtɜːrn/","gloss":"de volta"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-04-02', 'lesson-shopping-a2-04', 2, 'sentence', 'Can I exchange it for a smaller size?', 'Posso trocar por um tamanho menor?', '/kæn aɪ ɪksˈtʃeɪndʒ ɪt fɔːr ə ˈsmɔːlər saɪz/', '"Exchange for" = trocar por.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"exchange","pos":"verb","ipa":"/ɪksˈtʃeɪndʒ/","gloss":"trocar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"smaller","pos":"adjective","ipa":"/ˈsmɔːlər/","gloss":"menor"},{"surface":"size","pos":"noun","ipa":"/saɪz/","gloss":"tamanho"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-04-03', 'lesson-shopping-a2-04', 3, 'sentence', 'Do you have the receipt?', 'Você tem o recibo?', '/duː juː hæv ðə rɪˈsiːt/', 'Pergunta comum antes de qualquer troca.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"receipt","pos":"noun","ipa":"/rɪˈsiːt/","gloss":"recibo"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-04-04', 'lesson-shopping-a2-04', 4, 'sentence', 'It doesn''t work.', 'Não está funcionando.', '/ɪt ˈdʌzənt wɜːrk/', '"Work" = funcionar.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"doesn''t","pos":"verb","ipa":"/ˈdʌzənt/","gloss":"não (does not)"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-04-05', 'lesson-shopping-a2-04', 5, 'sentence', 'It was damaged when I opened it.', 'Estava danificado quando abri.', '/ɪt wɑːz ˈdæmɪdʒd wɛn aɪ ˈoʊpənd ɪt/', 'Passado com "when": "when I opened it".', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"damaged","pos":"adjective","ipa":"/ˈdæmɪdʒd/","gloss":"danificado"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"opened","pos":"verb","ipa":"/ˈoʊpənd/","gloss":"abriu"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-04-06', 'lesson-shopping-a2-04', 6, 'sentence', 'Can I get a refund?', 'Posso ter o dinheiro de volta?', '/kæn aɪ ɡɛt ə ˈriːfʌnd/', '"Refund" = reembolso.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"refund","pos":"noun","ipa":"/ˈriːfʌnd/","gloss":"reembolso"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-04-07', 'lesson-shopping-a2-04', 7, 'sentence', 'What''s your return policy?', 'Qual é a política de devolução?', '/wʌts jʊr rɪˈtɜːrn ˈpɑːləsi/', '"Return policy" = regras de troca e devolução.', '[]'::jsonb, '[{"surface":"What''s","pos":"pronoun","ipa":"/wʌts/","gloss":"qual é"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"return","pos":"adjective","ipa":"/rɪˈtɜːrn/","gloss":"de volta"},{"surface":"policy","pos":"noun","ipa":"/ˈpɑːləsi/","gloss":"política, regra"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-04-08', 'lesson-shopping-a2-04', 8, 'sentence', 'You have thirty days to return it.', 'Você tem trinta dias para devolver.', '/juː hæv ˈθɜːrti deɪz tuː rɪˈtɜːrn ɪt/', '"Have" + prazo + "to" + verbo.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"thirty","pos":"numeral","ipa":"/ˈθɜːrti/","gloss":"trinta"},{"surface":"days","pos":"noun","ipa":"/deɪz/","gloss":"dias"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"return","pos":"adjective","ipa":"/rɪˈtɜːrn/","gloss":"de volta"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-04-09', 'lesson-shopping-a2-04', 9, 'sentence', 'We can only give you store credit.', 'Só podemos dar crédito na loja.', '/wiː kæn ˈoʊnli ɡɪv juː stɔːr ˈkrɛdɪt/', '"Store credit" = vale para usar na própria loja.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"give","pos":"verb","ipa":"/ɡɪv/","gloss":"dar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"credit","pos":"noun","ipa":"/ˈkrɛdɪt/","gloss":"crédito"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-04-10', 'lesson-shopping-a2-04', 10, 'sentence', 'I never used it.', 'Eu nunca usei.', '/aɪ ˈnɛvər juːzd ɪt/', 'Passado simples + "never".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-shopping-a2-05-01', 'lesson-shopping-a2-05', 1, 'sentence', 'I ordered it online last week.', 'Pedi pela internet semana passada.', '/aɪ ˈɔːrdərd ɪt ˌɑːnˈlaɪn læst wiːk/', '"Order" = pedir, encomendar. "Online" = pela internet.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"ordered","pos":"verb","ipa":"/ˈɔːrdərd/","gloss":"pediu, pedido"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"online","pos":"adverb","ipa":"/ˌɑːnˈlaɪn/","gloss":"na internet"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-05-02', 'lesson-shopping-a2-05', 2, 'sentence', 'Is shipping free?', 'O frete é grátis?', '/ɪz ˈʃɪpɪŋ friː/', '"Shipping" = frete, envio.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"shipping","pos":"noun","ipa":"/ˈʃɪpɪŋ/","gloss":"frete"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-05-03', 'lesson-shopping-a2-05', 3, 'sentence', 'When will it arrive?', 'Quando vai chegar?', '/wɛn wɪl ɪt əˈraɪv/', 'Futuro com "will" em pergunta.', '[]'::jsonb, '[{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-05-04', 'lesson-shopping-a2-05', 4, 'sentence', 'My order is late.', 'Meu pedido está atrasado.', '/maɪ ˈɔːrdər ɪz leɪt/', '"Order" como substantivo = pedido.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"order","pos":"verb","ipa":"/ˈɔːrdər/","gloss":"pedir (comida)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-05-05', 'lesson-shopping-a2-05', 5, 'sentence', 'Can I track my package?', 'Posso rastrear meu pacote?', '/kæn aɪ træk maɪ ˈpækɪdʒ/', '"Track" = rastrear. "Package" = pacote.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"track","pos":"noun","ipa":"/træk/","gloss":"trilha, caminho"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"package","pos":"noun","ipa":"/ˈpækɪdʒ/","gloss":"pacote"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-05-06', 'lesson-shopping-a2-05', 6, 'sentence', 'It was delivered to the wrong address.', 'Foi entregue no endereço errado.', '/ɪt wɑːz dɪˈlɪvərd tuː ðə rɔːŋ ˈædrɛs/', 'Voz passiva no passado: "was delivered".', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"delivered","pos":"verb","ipa":"/dɪˈlɪvərd/","gloss":"entregue"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"wrong","pos":"adjective","ipa":"/rɔːŋ/","gloss":"errado"},{"surface":"address","pos":"noun","ipa":"/ˈædrɛs/","gloss":"endereço"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-05-07', 'lesson-shopping-a2-05', 7, 'sentence', 'Nobody was home when they came.', 'Não tinha ninguém em casa quando eles vieram.', '/ˈnoʊbɑːdi wɑːz hoʊm wɛn ðeɪ keɪm/', '"Nobody was" = não tinha ninguém.', '[]'::jsonb, '[{"surface":"Nobody","pos":"pronoun","ipa":"/ˈnoʊbɑːdi/","gloss":"ninguém"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"came","pos":"verb","ipa":"/keɪm/","gloss":"veio"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-05-08', 'lesson-shopping-a2-05', 8, 'sentence', 'I want to cancel my order.', 'Quero cancelar meu pedido.', '/aɪ wɑːnt tuː ˈkænsəl maɪ ˈɔːrdər/', '"Cancel" = cancelar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"cancel","pos":"verb","ipa":"/ˈkænsəl/","gloss":"cancelar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"order","pos":"verb","ipa":"/ˈɔːrdər/","gloss":"pedir (comida)"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-05-09', 'lesson-shopping-a2-05', 9, 'sentence', 'The item is out of stock.', 'O item está esgotado.', '/ðə ˈaɪtəm ɪz aʊt ʌv stɑːk/', '"Out of stock" = sem estoque.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"item","pos":"noun","ipa":"/ˈaɪtəm/","gloss":"item"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"stock","pos":"noun","ipa":"/stɑːk/","gloss":"estoque"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-05-10', 'lesson-shopping-a2-05', 10, 'sentence', 'Please leave it at the door.', 'Por favor, deixe na porta.', '/pliːz liːv ɪt æt ðə dɔːr/', 'Instrução comum para entregadores.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-shopping-a2-06-01', 'lesson-shopping-a2-06', 1, 'sentence', 'I''m not happy with this product.', 'Não estou satisfeito com este produto.', '/aɪm nɑːt ˈhæpi wɪð ðɪs ˈprɑːdʌkt/', '"Happy with" = satisfeito com.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"happy","pos":"adjective","ipa":"/ˈhæpi/","gloss":"feliz"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"product","pos":"noun","ipa":"/ˈprɑːdʌkt/","gloss":"produto"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-06-02', 'lesson-shopping-a2-06', 2, 'sentence', 'I''d like to make a complaint.', 'Eu gostaria de fazer uma reclamação.', '/aɪd laɪk tuː meɪk ə kəmˈpleɪnt/', '"Make a complaint" = reclamar formalmente.', '[]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"complaint","pos":"noun","ipa":"/kəmˈpleɪnt/","gloss":"reclamação"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-06-03', 'lesson-shopping-a2-06', 3, 'sentence', 'I was charged twice.', 'Fui cobrado duas vezes.', '/aɪ wɑːz tʃɑːrdʒd twaɪs/', 'Voz passiva: "was charged".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"charged","pos":"verb","ipa":"/tʃɑːrdʒd/","gloss":"cobrado"},{"surface":"twice","pos":"adverb","ipa":"/twaɪs/","gloss":"duas vezes"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-06-04', 'lesson-shopping-a2-06', 4, 'sentence', 'This is not what I ordered.', 'Isto não é o que eu pedi.', '/ðɪs ɪz nɑːt wʌt aɪ ˈɔːrdərd/', '"What I ordered" = o que eu pedi.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"ordered","pos":"verb","ipa":"/ˈɔːrdərd/","gloss":"pediu, pedido"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-06-05', 'lesson-shopping-a2-06', 5, 'sentence', 'Can I speak to the manager, please?', 'Posso falar com o gerente, por favor?', '/kæn aɪ spiːk tuː ðə ˈmænɪdʒər pliːz/', 'Pedido educado; "please" evita soar agressivo.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"speak","pos":"verb","ipa":"/spiːk/","gloss":"falar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"manager","pos":"noun","ipa":"/ˈmænɪdʒər/","gloss":"gerente"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-06-06', 'lesson-shopping-a2-06', 6, 'sentence', 'I''ve been waiting for two weeks.', 'Estou esperando há duas semanas.', '/aɪv bɪn ˈweɪtɪŋ fɔːr tuː wiːks/', 'Present perfect contínuo + "for": ainda está esperando.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"waiting","pos":"verb","ipa":"/ˈweɪtɪŋ/","gloss":"esperando"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"weeks","pos":"noun","ipa":"/wiːks/","gloss":"semanas"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-06-07', 'lesson-shopping-a2-06', 7, 'sentence', 'What can you do about it?', 'O que vocês podem fazer a respeito?', '/wʌt kæn juː duː əˈbaʊt ɪt/', '"About it" = a respeito disso.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-06-08', 'lesson-shopping-a2-06', 8, 'sentence', 'I understand, but this is not fair.', 'Entendo, mas isso não é justo.', '/aɪ ˌʌndərˈstænd bʌt ðɪs ɪz nɑːt fɛr/', '"I understand, but" mostra empatia e mantém o pedido.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"understand","pos":"verb","ipa":"/ˌʌndərˈstænd/","gloss":"entender"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"fair","pos":"adjective","ipa":"/fɛr/","gloss":"justo"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-06-09', 'lesson-shopping-a2-06', 9, 'sentence', 'Thank you for solving this.', 'Obrigado por resolver.', '/θæŋk juː fɔːr ˈsɑːlvɪŋ ðɪs/', '"Thank you for" + verbo com "-ing".', '[]'::jsonb, '[{"surface":"Thank","pos":"verb","ipa":"/θæŋk/","gloss":"agradecer"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"solving","pos":"verb","ipa":"/ˈsɑːlvɪŋ/","gloss":"resolver"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"}]'::jsonb, NULL, NULL),
  ('unit-shopping-a2-06-10', 'lesson-shopping-a2-06', 10, 'sentence', 'I''ll leave a review.', 'Vou deixar uma avaliação.', '/aɪl liːv ə rɪˈvjuː/', '"Leave a review" = avaliar a loja.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"review","pos":"noun","ipa":"/rɪˈvjuː/","gloss":"avaliação"}]'::jsonb, NULL, NULL)
